const fs = await import('node:fs');
const path = await import('node:path');
const imgPath = globalThis.input.image_path;
const outPath = globalThis.input.output_path;
if (!fs.existsSync(imgPath)) {
  throw new Error('Input image not found: ' + imgPath);
}
const outDir = path.dirname(outPath);
if (!fs.existsSync(outDir)) {
  fs.mkdirSync(outDir, { recursive: true });
}
globalThis.imgPath = imgPath;
globalThis.outPath = outPath;
